/**
 * Supported currencies for item listings and bidder display.
 * @trace DSN-012 REQ-001 REQ-005
 */
export enum Currency { CHF = 'CHF', EUR = 'EUR', USD = 'USD' }

/**
 * Lifecycle state of an item auction.
 *
 * @trace DSN-013 REQ-001 REQ-004
 */
export enum AuctionStatus { open = 'open', closed = 'closed', unsold = 'unsold' }

/**
 * A user identified by a unique display name, with no password.
 *
 * @trace DSN-014 REQ-008
 */
export class User {
  constructor(public id: string, public displayName: string) {
    if (id.length === 0) {
      throw new Error('User id must not be empty');
    }
    const length = displayName.trim().length;
    if (length < 2 || length > 20) {
      throw new Error('Display name must be 2 to 20 characters');
    }
  }
}

/**
 * Accepted bid stored in item currency.
 *
 * @trace DSN-016 REQ-002
 */
export class Bid {
  constructor(
    public id: string,
    public itemId: string,
    public bidderId: string,
    public amount: number,
    public placedAt: Date,
  ) {}
}

import { Item } from './Item.js';
import { Currency } from './Currency.js';

/**
 * Item as shown to a client, with optional converted prices.
 *
 * @trace DSN-017 REQ-005 REQ-010
 */
export interface ItemView {
  item: Item;
  displayCurrency: Currency | null;
  convertedStartingPrice: number | null;
