import { ItemService } from './ItemService.js';

/**
 * Periodic job that closes auctions whose end time was reached.
 * @trace DSN-024 REQ-004
 */
export class AuctionCloser {
  /** Validates intervalMs, which must be a positive integer. */
  constructor(private readonly itemService: ItemService, public intervalMs: number) {
    if (!Number.isInteger(intervalMs) || intervalMs <= 0) {
      throw new Error('intervalMs must be a positive integer');
    }
  }

  /** Closes every auction whose end time has been reached at the current time. */
  async tick(): Promise<void> {
    await this.itemService.closeDueAuctions(new Date());
  }
}

import { randomUUID } from 'node:crypto';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { AuctionEventPublisher } from './AuctionEventPublisher.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

/**
 * Creates and reads items, and closes auctions whose end time has been reached.
 * @trace DSN-022 REQ-001 REQ-004
 */
export class ItemService {
  constructor(private readonly itemStore: ItemStore, private readonly userStore: UserStore, private readonly auctionEventPublisher: AuctionEventPublisher) {}

  /** Lists a new open item for an existing seller; throws on invalid input or unknown seller. */
  async listItem(sellerId: string, title: string, startingPrice: number, endTime: Date, currency: string): Promise<Item> {
    if (typeof sellerId !== 'string' || sellerId.trim() === '') {
      throw new Error('sellerId must be a non-empty string');
    }
    const seller = await this.userStore.findById(sellerId);
    if (seller === null) {
      throw new Error(`User ${sellerId} not found`);
    }
    if (typeof title !== 'string' || title.trim() === '') {
      throw new Error('title must be a non-empty string');
    }
    if (typeof startingPrice !== 'number' || !Number.isFinite(startingPrice) || startingPrice < 0) {
      throw new Error('startingPrice must be a non-negative number');
    }
    if (!(endTime instanceof Date) || Number.isNaN(endTime.getTime())) {
      throw new Error('endTime must be a valid date');
    }
    if (!(Object.values(Currency) as string[]).includes(currency)) {
      throw new Error('currency must be one of CHF, EUR, USD');
    }
    const item = new Item(
      randomUUID(),
      sellerId,
      title,
      startingPrice,
      currency as Currency,
      endTime,
      AuctionStatus.open,
      null,
      null,
      null,
    );
    return this.itemStore.saveItem(item);
  }

  /** Returns the item with the given id; throws if the id is invalid or the item is not found. */
  async getItem(id: string): Promise<Item> {
    if (typeof id !== 'string' || id.trim() === '') {
      throw new Error('id must be a non-empty string');
    }
    const item = await this.itemStore.findItem(id);
    if (item === null) {
      throw new Error(`Item ${id} not found`);
    }
    return item;
  }

  /** Returns all items whose auctions are currently open. */
  async listOpenItems(): Promise<Item[]> {
    return this.itemStore.findOpenItems();
  }

  /** Closes every open auction due at the given time, marking winners or unsold items and publishing each closure. */
  async closeDueAuctions(now: Date): Promise<void> {
    if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
      throw new Error('now must be a valid date');
    }
    const dueItems = await this.itemStore.findDueItems(now);
    for (const item of dueItems) {
      if (item.highestBidAmount === null || item.highestBidderId === null) {
        item.status = AuctionStatus.unsold;
        item.winnerId = null;
      } else {
        item.status = AuctionStatus.closed;
        item.winnerId = item.highestBidderId;
      }
      await this.itemStore.saveItem(item);
      await this.auctionEventPublisher.publishAuctionClosed(item);
    }
  }
}

import { randomUUID } from 'node:crypto';
import { Bid } from './Bid.js';
import { Item } from './Item.js';
import { ItemStore } from './ItemStore.js';
import { UserStore } from './UserStore.js';
import { BidEventPublisher } from './BidEventPublisher.js';

/**
 * Validates and stores bids, extends end time, and publishes accepted bids to the event feed.
 *
 * @trace DSN-023 REQ-002 REQ-009 REQ-003 REQ-011
 */
export class BidService {
  constructor(
    private readonly itemStore: ItemStore,
    private readonly bidEventPublisher: BidEventPublisher,
    private readonly userStore: UserStore,
  ) {}

  /** Validates a bid, extends the end time when late, stores it and publishes it; throws on invalid input, unknown item or user, or a rejected bid. */
  async placeBid(itemId: string, bidderId: string, amount: number): Promise<Bid> {
    if (typeof itemId !== 'string' || itemId.length === 0) {
      throw new Error('itemId must be a non-empty string');
    }
    if (typeof bidderId !== 'string' || bidderId.length === 0) {
      throw new Error('bidderId must be a non-empty string');
    }
    if (typeof amount !== 'number' || !Number.isFinite(amount) || amount <= 0) {
      throw new Error('amount must be a positive number');
    }

    const item: Item | null = await this.itemStore.findItem(itemId);
    if (item === null) {
      throw new Error(`Item ${itemId} not found`);
    }
    const bidder = await this.userStore.findById(bidderId);
    if (bidder === null) {
      throw new Error(`User ${bidderId} not found`);
    }

    const now = new Date();
    if (item.sellerId === bidderId) {
      throw new Error('Seller cannot bid on their own item');
    }
    if (!item.isOpen(now)) {
      throw new Error(`Item ${itemId} is not open for bids`);
    }
    if (amount < item.minimumBid()) {
      throw new Error(`Bid ${amount} is below the minimum bid ${item.minimumBid()}`);
    }

    item.extendIfLate(now);
    const bid = new Bid(randomUUID(), itemId, bidderId, amount, now);
    item.recordBid(bid);

    const savedBid = await this.itemStore.saveBid(bid);
    await this.itemStore.saveItem(item);
    await this.bidEventPublisher.publishBidAccepted(savedBid, item);
    return savedBid;
  }
}

import { Currency } from '../auction-api/Currency.js';
import { FrankfurterClient } from './FrankfurterClient.js';

interface CachedRates {
  fetchedAt: number;
  rates: Record<string, number>;
}

/**
 * Converts prices for display using rates cached for a configurable time; returns null when unavailable.
 * @trace DSN-025 REQ-005 REQ-010
 */
export class ExchangeRateService {
  private readonly cache = new Map<Currency, CachedRates>();

  constructor(private readonly frankfurterClient: FrankfurterClient, public cacheTtlMs: number) {}

  /** Converts an item-currency amount to the display currency, returning null when no rate is available; throws on invalid input. */
  async convert(amount: number, from: Currency, to: Currency): Promise<number | null> {
    if (!Number.isFinite(amount) || amount < 0) {
      throw new Error('amount must be a non-negative finite number');
    }
    if (!Object.values(Currency).includes(from)) {
      throw new Error(`from currency ${String(from)} is not supported`);
    }
    if (!Object.values(Currency).includes(to)) {
      throw new Error(`to currency ${String(to)} is not supported`);
    }
    if (from === to) {
      return amount;
    }
    const rates = await this.ratesFor(from);
    if (rates === null) {
      return null;
    }
    const rate = rates[to];
    if (typeof rate !== 'number' || !Number.isFinite(rate)) {
      return null;
    }
    return amount * rate;
  }

  private async ratesFor(base: Currency): Promise<Record<string, number> | null> {
    const cached = this.cache.get(base);
    const now = Date.now();
    if (cached !== undefined && now - cached.fetchedAt < this.cacheTtlMs) {
      return cached.rates;
    }
    try {
      const rates = await this.frankfurterClient.fetchRates(base);
      this.cache.set(base, { fetchedAt: now, rates });
      return rates;
    } catch {
      return null;
    }
  }
}

import { Currency } from '../auction-api/Currency.js';

const FRANKFURTER_URL = 'https://api.frankfurter.app/latest';
const CACHE_TTL_MS = 60 * 60 * 1000;
const REQUEST_TIMEOUT_MS = 5000;

interface CachedRates {
  rates: Record<string, number>;
  fetchedAt: number;
}

/**
 * Fetches exchange rates from the Frankfurter API and caches them for one hour.
 * @trace DSN-026 REQ-005 REQ-010
 */
export class FrankfurterClient {
  private readonly cache = new Map<Currency, CachedRates>();

  /** Returns rates for the base currency, using the cache when it is under one hour old; returns an empty record when Frankfurter is unreachable and no valid cache exists. */
  async fetchRates(base: Currency): Promise<Record<string, number>> {
    if (!Object.values(Currency).includes(base)) {
      throw new Error(`Unsupported base currency: ${String(base)}`);
    }
    const cached = this.cache.get(base);
    if (cached && Date.now() - cached.fetchedAt < CACHE_TTL_MS) {
      return { ...cached.rates };
    }
    try {
      const response = await fetch(`${FRANKFURTER_URL}?from=${base}`, {
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
      if (!response.ok) {
        throw new Error(`Frankfurter responded with status ${response.status}`);
      }
      const body = (await response.json()) as { rates?: Record<string, number> };
      if (!body.rates || typeof body.rates !== 'object') {
        throw new Error('Frankfurter response has no rates');
      }
      const rates: Record<string, number> = { ...body.rates };
      this.cache.set(base, { rates, fetchedAt: Date.now() });
      return { ...rates };
    } catch {
      return {};
    }
  }
}

import { DatabaseSync } from 'node:sqlite';
import { User } from './User.js';

/**
 * Persists users with a unique display name in the API server's SQLite database.
 *
 * @trace DSN-028 REQ-008
 */
export class UserStore {
  /** Creates the users table if it does not exist. */
  constructor(db: DatabaseSync) {
    this.db = db;
    this.db.exec(
      'CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, display_name TEXT NOT NULL UNIQUE)'
    );
  }

  private readonly db: DatabaseSync;

  /** Returns the user with the given display name, or null when none has it. */
  async findByName(displayName: string): Promise<User | null> {
    if (typeof displayName !== 'string' || displayName.length === 0) {
      throw new Error('displayName must be a non-empty string');
    }
    const rows = this.db
      .prepare('SELECT id, display_name FROM users WHERE display_name = ?')
      .all(displayName) as unknown as { id: string; display_name: string }[];
    return rows.length === 0 ? null : this.toUser(rows[0]);
  }

  /** Inserts the user when its id is not stored yet, otherwise updates its display name; throws when the id is empty or the display name is taken. */
  async save(user: User): Promise<User> {
    if (typeof user.id !== 'string' || user.id.length === 0) {
      throw new Error('user.id must be a non-empty string');
    }
    const exists = this.db
      .prepare('SELECT id FROM users WHERE id = ?')
      .all(user.id) as unknown as { id: string }[];
    if (exists.length === 0) {
      this.db
        .prepare('INSERT INTO users (id, display_name) VALUES (?, ?)')
        .run(user.id, user.displayName);
    } else {
      this.db
        .prepare('UPDATE users SET display_name = ? WHERE id = ?')
        .run(user.displayName, user.id);
    }
    return user;
  }

  /** Returns the user with the given id, or null when none has it; throws when the id is empty. */
  async findById(id: string): Promise<User | null> {
    if (typeof id !== 'string' || id.length === 0) {
      throw new Error('id must be a non-empty string');
    }
    const rows = this.db
      .prepare('SELECT id, display_name FROM users WHERE id = ?')
      .all(id) as unknown as { id: string; display_name: string }[];
    return rows.length === 0 ? null : this.toUser(rows[0]);
  }

  private toUser(row: { id: string; display_name: string }): User {
    return new User(row.id, row.display_name);
  }
}

import { EventFeed } from './EventFeed.js';
import { Item } from './Item.js';

/**
 * Publishes auction closed events to the internal ws event feed.
 *
 * @trace DSN-030 REQ-003 REQ-004 REQ-007
 */
export class AuctionEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes the closed state and winner of an item to its watchers; throws Error if the item has no id. */
  async publishAuctionClosed(item: Item): Promise<void> {
    if (typeof item.id !== 'string' || item.id.length === 0) {
      throw new Error('item.id must be a non-empty string');
    }
    const payload = JSON.stringify({
      type: 'auction_closed',
      itemId: item.id,
      status: item.status,
      winnerId: item.winnerId,
      highestBidAmount: item.highestBidAmount,
    });
    this.eventFeed.publish(`item:${item.id}`, payload);
  }
}

