import { Bid } from './Bid.js';
import { Item } from './Item.js';
import { EventFeed } from './EventFeed.js';

/**
 * Publishes accepted bid events to the internal ws event feed.
 *
 * @trace DSN-031 REQ-003 REQ-007 REQ-011
 */
export class BidEventPublisher {
  constructor(private readonly eventFeed: EventFeed) {}

  /** Publishes an accepted bid to the item's topic; throws if the bid does not belong to the item. */
  async publishBidAccepted(bid: Bid, item: Item): Promise<void> {
    if (bid.itemId !== item.id) {
      throw new Error(`Bid ${bid.id} does not belong to item ${item.id}`);
    }
    const payload = JSON.stringify({
      bidId: bid.id,
      itemId: item.id,
      bidderId: bid.bidderId,
      amount: bid.amount,
      placedAt: bid.placedAt.toISOString(),
      highestBidAmount: item.highestBidAmount,
      highestBidderId: item.highestBidderId,
      endTime: item.endTime.toISOString(),
      status: item.status,
    });
    this.eventFeed.publish(`item:${item.id}`, payload);
  }
}

import { DatabaseSync } from 'node:sqlite';
import { Item } from './Item.js';
import { Bid } from './Bid.js';
import { Currency } from './Currency.js';
import { AuctionStatus } from './AuctionStatus.js';

/**
 * Persistence of items and bids, in the API server's SQLite database.
 *
 * @trace DSN-029 REQ-001 REQ-002 REQ-004
 */
export class ItemStore {
  private readonly db: DatabaseSync;

  constructor(db: DatabaseSync) {
    this.db = db;
    this.db.exec(`CREATE TABLE IF NOT EXISTS items (
      id TEXT PRIMARY KEY,
      sellerId TEXT NOT NULL,
      title TEXT NOT NULL,
      startingPrice REAL NOT NULL,
      currency TEXT NOT NULL,
      endTime TEXT NOT NULL,
      status TEXT NOT NULL,
      highestBidAmount REAL,
      highestBidderId TEXT,
      winnerId TEXT
    )`);
    this.db.exec(`CREATE TABLE IF NOT EXISTS bids (
      id TEXT PRIMARY KEY,
      itemId TEXT NOT NULL,
      bidderId TEXT NOT NULL,
      amount REAL NOT NULL,
      placedAt TEXT NOT NULL
    )`);
  }

  /** Inserts the item if its id is new, otherwise updates its stored row. */
  async saveItem(item: Item): Promise<Item> {
    const exists = this.db.prepare('SELECT id FROM items WHERE id = ?').get(item.id) !== undefined;
    if (exists) {
      this.db
        .prepare(`UPDATE items SET sellerId = ?, title = ?, startingPrice = ?, currency = ?, endTime = ?,
          status = ?, highestBidAmount = ?, highestBidderId = ?, winnerId = ? WHERE id = ?`)
        .run(
          item.sellerId,
          item.title,
          item.startingPrice,
          item.currency,
          item.endTime.toISOString(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
          item.id,
        );
    } else {
      this.db
        .prepare(`INSERT INTO items (id, sellerId, title, startingPrice, currency, endTime, status,
          highestBidAmount, highestBidderId, winnerId) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`)
        .run(
          item.id,
          item.sellerId,
          item.title,
          item.startingPrice,
          item.currency,
          item.endTime.toISOString(),
          item.status,
          item.highestBidAmount,
          item.highestBidderId,
          item.winnerId,
        );
    }
    return item;
  }

  /** Returns the item with the given id, or null when it is not stored. */
  async findItem(id: string): Promise<Item | null> {
    const row = this.db.prepare('SELECT * FROM items WHERE id = ?').get(id);
    if (row === undefined) {
      return null;
    }
    return this.toItem(row as unknown as ItemRow);
  }

  /** Returns all items whose status is open. */
  async findOpenItems(): Promise<Item[]> {
    const rows = this.db
      .prepare('SELECT * FROM items WHERE status = ?')
      .all(AuctionStatus.open) as unknown as ItemRow[];
    return rows.map((row) => this.toItem(row));
  }

  /** Returns the open items whose end time is not after the given instant. */
  async findDueItems(now: Date): Promise<Item[]> {
    const open = await this.findOpenItems();
    return open.filter((item) => item.endTime.getTime() <= now.getTime());
  }

  /** Inserts the bid if its id is new, otherwise updates its stored row. */
  async saveBid(bid: Bid): Promise<Bid> {
    const exists = this.db.prepare('SELECT id FROM bids WHERE id = ?').get(bid.id) !== undefined;
    if (exists) {
      this.db
        .prepare('UPDATE bids SET itemId = ?, bidderId = ?, amount = ?, placedAt = ? WHERE id = ?')
        .run(bid.itemId, bid.bidderId, bid.amount, bid.placedAt.toISOString(), bid.id);
    } else {
      this.db
        .prepare('INSERT INTO bids (id, itemId, bidderId, amount, placedAt) VALUES (?, ?, ?, ?, ?)')
        .run(bid.id, bid.itemId, bid.bidderId, bid.amount, bid.placedAt.toISOString());
    }
    return bid;
  }

  private toItem(row: ItemRow): Item {
    return new Item(
      row.id,
      row.sellerId,
      row.title,
      row.startingPrice,
      row.currency as Currency,
      new Date(row.endTime),
      row.status as AuctionStatus,
      row.highestBidAmount,
      row.highestBidderId,
      row.winnerId,
    );
  }
}

type ItemRow = {
  id: string;
  sellerId: string;
  title: string;
  startingPrice: number;
  currency: string;
  endTime: string;
  status: string;
  highestBidAmount: number | null;
  highestBidderId: string | null;
  winnerId: string | null;
};

import { WebSocket } from 'ws';

/**
 * Holds the sockets of connected live server instances and fans out published events to all of them.
 *
 * @trace DSN-034 REQ-003 REQ-007 REQ-011
 */
export class EventFeed {
  constructor(public clients: Set<WebSocket>) {}

  /** Sends the topic and payload to every held open socket and drops sockets that are no longer open; throws if the topic is empty. */
  publish(topic: string, payload: string): void {
    if (typeof topic !== 'string' || topic.length === 0) {
      throw new Error('topic must be a non-empty string');
    }
    const message = JSON.stringify({ topic, payload });
    for (const socket of this.clients) {
      if (socket.readyState !== WebSocket.OPEN) {
        this.clients.delete(socket);
        continue;
      }
      socket.send(message);
    }
  }
}

import { WebSocket } from 'ws';
import { LiveGateway } from './LiveGateway.js';

const RECONNECT_DELAY_MS = 1000;
const HANDLED_TOPICS = ['bid.accepted', 'item.watch', 'auction.closed'];

/**
 * Client of the API server's internal ws event feed that hands incoming events to the live gateway.
 * @trace DSN-032 REQ-003 REQ-007 REQ-011
 */
export class EventFeedClient {
  private socket: WebSocket | null = null;
  private reconnectTimer: NodeJS.Timeout | null = null;

  constructor(private readonly liveGateway: LiveGateway) {}

  /** Opens the ws to the API server and reopens it after a close; no error is thrown. */
  connect(): void {
    const url = process.env.API_SERVER_URL ?? 'ws://localhost:8080';
    const socket = new WebSocket(`${url}/internal/live-update-server`);
    this.socket = socket;
    socket.on('message', (data) => {
      const text = data.toString();
      try {
        const event = JSON.parse(text) as { topic?: unknown; payload?: unknown };
        if (typeof event.topic !== 'string' || typeof event.payload !== 'string') {
          return;
        }
        this.onEvent(event.topic, event.payload);
      } catch {
        return;
      }
    });
    socket.on('close', () => {
      this.socket = null;
      this.reconnectTimer = setTimeout(() => {
        this.reconnectTimer = null;
        this.connect();
      }, RECONNECT_DELAY_MS);
    });
    socket.on('error', () => {
      socket.close();
    });
  }

  /** Hands an event to the gateway for the item it names; throws an Error for an unknown topic or a payload without itemId. */
  onEvent(topic: string, payload: string): void {
    if (!HANDLED_TOPICS.includes(topic)) {
      throw new Error(`Unknown topic ${topic}`);
    }
    let itemId: unknown;
    try {
      itemId = (JSON.parse(payload) as { itemId?: unknown }).itemId;
    } catch {
      throw new Error('Payload must be JSON with an itemId');
    }
    if (typeof itemId !== 'string' || itemId.length === 0) {
      throw new Error('Payload must be JSON with an itemId');
    }
    this.liveGateway.broadcast(itemId, payload);
  }
}

import { WebSocket } from 'ws';

/**
 * WebSocket gateway that pushes each bid update only to the browser sockets watching that item.
 * @trace DSN-033 REQ-003 REQ-009 REQ-011 REQ-004
 */
export class LiveGateway {
  private watchers: Map<string, Set<string>> = new Map();

  /** Keeps the open browser sockets by client id. */
  constructor(public sockets: Map<string, WebSocket>) {}

  /** Adds the client as a watcher of the item; throws if the id is empty or the client has no open socket. */
  watch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    if (!this.sockets.has(clientId)) {
      throw new Error(`Client ${clientId} not found`);
    }
    let set = this.watchers.get(itemId);
    if (!set) {
      set = new Set<string>();
      this.watchers.set(itemId, set);
    }
    set.add(clientId);
  }

  /** Removes the client from the watchers of the item; throws if an id is empty. */
  unwatch(clientId: string, itemId: string): void {
    this.checkId(clientId, 'clientId');
    this.checkId(itemId, 'itemId');
    const set = this.watchers.get(itemId);
    if (!set) {
      return;
    }
    set.delete(clientId);
    if (set.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  /** Sends the message to every open socket watching the item; throws if the item id is empty. */
  broadcast(itemId: string, message: string): void {
    this.checkId(itemId, 'itemId');
    const set = this.watchers.get(itemId);
    if (!set) {
      return;
    }
    for (const clientId of [...set]) {
      const socket = this.sockets.get(clientId);
      if (!socket || socket.readyState !== WebSocket.OPEN) {
        set.delete(clientId);
        continue;
      }
      socket.send(message);
    }
    if (set.size === 0) {
      this.watchers.delete(itemId);
    }
  }

  private checkId(value: string, name: string): void {
    if (typeof value !== 'string' || value.trim() === '') {
      throw new Error(`${name} must be a non-empty string`);
    }
  }
}

